message.content:
{
  "description": "The creature is shown in right-facing profile standing on a patch of rocky ground. It has the head, neck fur, hind legs, paws and bushy tail of a gray wolf, but its torso, back, belly and all four limbs are covered in a dark bluish-gray, glossy, segmented crustacean exoskeleton. A row of spiny, serrated plates runs along the midline of the back from the shoulders to the base of the tail, with large overlapping carapace plates covering the shoulders and back and smaller banded plates covering the sides, belly and limbs. The two front limbs are greatly enlarged, heavily armored chelipeds ending in large pincer claws that rest on the ground, while the two hind limbs are canine in shape with fur on the lower legs and paws but armored plating over the thighs and shanks.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a wolf head in right profile with gray, white and tan fur, a long pointed muzzle, black nose, amber-brown eye, and white whisker pads",
      "where": "at the front end of the body, attached to the furry neck"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, fur-covered wolf ears with dark outer fur and lighter inner fur",
      "where": "on top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "four legs: the front pair are thick, jointed, heavily armored crustacean chelipeds with spiny dark exoskeleton and bulbous segments; the hind pair are canine legs with gray fur and dark banded armor over the upper thigh and shank",
      "where": "two front legs under the chest/shoulder, two hind legs under the rear body"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are light-colored canine paws with dark claws and fur at the ankle; front feet are large dark crab-like pincers (chelae) with a movable finger and spiny outer surface, tips touching the ground",
      "where": "at the ends of the four legs, two paws at the rear and two claws at the front"
    },
    {
      "part": "tail",
      "looks_like": "a long, thick, bushy wolf tail covered in long gray and black fur, tapering to a point",
      "where": "extending from the rear of the body, hanging down behind the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "a glossy, dark bluish-gray crustacean carapace forming large shoulder shields with spiny, scalloped edges and overlapping dorsal plates",
      "where": "covering the back, shoulders and sides from the base of the neck to the base of the tail"
    },
    {
      "part": "plates",
      "looks_like": "numerous overlapping, segmented, hard plates with golden-brown seams and spiny dorsal tubercles; lighter, ridged ventral plates on the belly and banded rings around the limbs",
      "where": "along the spine, across the back and sides, on the belly, and as rings encircling the front and hind limbs"
    }
  ],
  "attached_objects": [],
  "animals": ["wolf", "crab"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
